const $=id=>document.getElementById(id),engine=QuickMindCommerce,fx=commercePreviewData.fx;
const registry=[{id:'DEMO-US-A001',status:'ACTIVE'},{id:'DEMO-US-PAUSED',status:'PAUSED'}];let activeCode='',currentQuote,activeDealer=null;
const usd=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
function localMoney(cents){const lang=$('language').value,currency=fx.currencyByLanguage[lang],digits=['JPY','KRW','IDR'].includes(currency)?0:2,rate=fx.rates[currency]/fx.rates.USD;return new Intl.NumberFormat(lang,{style:'currency',currency,currencyDisplay:'code',minimumFractionDigits:digits,maximumFractionDigits:digits}).format(Math.round(cents/100*rate*10**digits)/10**digits)}
function totals(){if(!$('quantity').reportValidity()||!$('commission').reportValidity()||!$('refund').reportValidity())return;currentQuote=engine.quote({code:activeCode,quantity:Number($('quantity').value)});const net=currentQuote.lines.map(l=>l.netCents);const currency=fx.currencyByLanguage[$('language').value],digits=['JPY','KRW','IDR'].includes(currency)?0:2,rate=fx.rates[currency]/fx.rates.USD;const displaySum=net.reduce((s,n)=>s+Math.round(n/100*rate*10**digits),0)/10**digits;const total=new Intl.NumberFormat($('language').value,{style:'currency',currency,currencyDisplay:'code',minimumFractionDigits:digits,maximumFractionDigits:digits}).format(displaySum);$('price-result').innerHTML='<dt>租赁费用（折后）</dt><dd>'+localMoney(net[0])+'</dd><dt>首年订阅（折后）</dt><dd>'+localMoney(net[1])+'</dd><dt>税费 / 运费</dt><dd>另计，待确认</dd><dt class="total">产品合计（折后）</dt><dd class="total">'+total+'</dd>';$('base-result').textContent='美元原价 '+usd(currentQuote.originalCents)+' · 优惠 '+usd(currentQuote.discountCents)+' · 折后产品金额 '+usd(currentQuote.productCents);$('refund').max=(currentQuote.productCents/100).toFixed(2);if(Number($('refund').value)*100>currentQuote.productCents)$('refund').value='0';activeDealer=engine.qualifyReferral({registry,requested:$('dealer').value,explicit:true});$('dealer-status').textContent=activeDealer?'归属：'+activeDealer.dealerId+'（样例，正式订单需服务器验证并锁定）':$('dealer').value?'该代理商已停用，不能获得归属或佣金。':'未归属代理商';$('referral-link').value=activeDealer?location.origin+location.pathname+'?dealer='+encodeURIComponent(activeDealer.dealerId):'';const refund=Math.round(Number($('refund').value)*100),bps=Math.round(Number($('commission').value)*100),basis=currentQuote.productCents-refund;const fee=activeDealer?engine.commission({paidProductCents:currentQuote.productCents,refundedProductCents:refund,commissionBasisPoints:bps}):0;$('commission-result').innerHTML='<dt>佣金基数（扣除产品退款）</dt><dd>'+usd(basis)+'</dd><dt>演示佣金</dt><dd>'+usd(fee)+'</dd><dt>状态</dt><dd>待真实付款，不进入正式账本</dd>';$('invoice-sample').hidden=true;return {refund,bps,basis,fee}}
$('discount-form').addEventListener('submit',e=>{e.preventDefault();try{const result=engine.quote({code:$('coupon').value,quantity:Number($('quantity').value)});activeCode=result.code;$('coupon-status').textContent=activeCode?'已应用预览代码 '+activeCode+' · 支付原价的 '+result.payBasisPoints/100+'%':'已恢复原价';totals()}catch{ $('coupon-status').textContent='代码或数量无效，保留上次有效报价。'}});
for(const id of ['quantity','language','dealer','commission','refund'])$(id).addEventListener('change',totals);
$('invoice-preview').addEventListener('click',()=>{const calc=totals();if(!calc)return;$('invoice-sample').hidden=false;$('invoice-sample').innerHTML='<article class="invoice"><p class="watermark">SAMPLE / NOT A VALID INVOICE · 设计样张，无真实付款、无邮件发送</p><h2>YIWEI USA INC · Invoice</h2><p>670 Lake Medlock Dr, Johns Creek, GA 30022, USA<br>yiweiinc99@gmail.com</p><p>Sample ID: SAMPLE-NOT-VALID<br>Bill to: Demo Customer<br>Order: DEMO-ORDER-NOT-REAL<br>Payment: DEMO-CAPTURE-NOT-REAL</p><table><thead><tr><th>Item</th><th>Qty</th><th>Original</th><th>Discount</th><th>Net (USD)</th></tr></thead><tbody>'+currentQuote.lines.map(l=>'<tr><td>'+(l.sku==='equipment-rental'?'Initial equipment rental':'First-year training subscription')+'</td><td>'+l.quantity+'</td><td>'+usd(l.originalCents)+'</td><td>'+usd(l.discountCents)+'</td><td>'+usd(l.netCents)+'</td></tr>').join('')+'</tbody></table><p>Illustrative product payment: <b>'+usd(currentQuote.productCents)+'</b><br>Tax & shipping: not specified in this sample<br>Service dates: to be confirmed from the order<br>Paid status: simulated only</p><p>真实流程会发送PDF及安全下载链接；本样张不能用于付款或报销。</p></article>'});
$('export-ledger').addEventListener('click',()=>{const calc=totals();if(!calc)return;const rows=[['scope','order_id','dealer_id','coupon','paid_product_USD_simulated','refund_USD_simulated','commission_base_USD_simulated','commission_percent_example','commission_USD_simulated','status'],['DEMO_NOT_A_SETTLEMENT','DEMO-ORDER-NOT-REAL',activeDealer?.dealerId||'NONE',activeCode||'NONE',(currentQuote.productCents/100).toFixed(2),(calc.refund/100).toFixed(2),(calc.basis/100).toFixed(2),(calc.bps/100).toFixed(2),(calc.fee/100).toFixed(2),'UNPAID_DEMO']];const blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='QuickMind-DEMO-not-a-settlement.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('implementation').appendChild(Object.assign(document.createElement('pre'),{textContent:commercePreviewData.spec}));const incoming=new URLSearchParams(location.search).get('dealer');if(registry.some(d=>d.id===incoming))$('dealer').value=incoming;totals();
